#!/usr/bin/env python3
"""Analyze synthetic-html-acceptance.csv and produce all report artifacts."""
import csv, json, os, datetime
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker

SRC_CSV = "/workspace/input/data/0/synthetic-html-acceptance.csv"
OUT_DIR = "/workspace/output/synthetic-acceptance-report"
CHART_PNG = os.path.join(OUT_DIR, "category_comparison.png")
RESULT_JSON = os.path.join(OUT_DIR, "result.json")
REPORT_HTML = os.path.join(OUT_DIR, "report.html")

# 1. Read & compute
rows = []
with open(SRC_CSV, newline="") as f:
    for r in csv.DictReader(f):
        rows.append({"category": r["category"].strip(), "amount": int(r["amount"].strip())})

count = len(rows)
total = sum(r["amount"] for r in rows)
mean = total / count if count else 0.0
print(f"Records: {count}, Total: {total}, Mean: {mean}")

# 2. RESULT JSON
result = {"count": count, "total": total, "mean": mean}
with open(RESULT_JSON, "w") as f:
    json.dump(result, f, indent=2)
print(f"Wrote {RESULT_JSON}")

# 3. Bar chart
categories = [r["category"] for r in rows]
amounts = [r["amount"] for r in rows]
colors = ["#5B8DB8", "#7BA67B", "#C4A35A"]
fig, ax = plt.subplots(figsize=(7, 4.5))
bars = ax.bar(categories, amounts, color=colors[:len(categories)], edgecolor="#333", linewidth=0.6)
for bar, val in zip(bars, amounts):
    ax.text(bar.get_x(), bar.get_height() + 0.5, str(val),
            ha="center", va="bottom", fontsize=12, fontweight="bold")
ax.set_xlabel("Category", fontsize=11)
ax.set_ylabel("Amount", fontsize=11)
ax.set_title("Category Comparison - Synthetic Acceptance Data", fontsize=13, fontweight="bold")
ax.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
ax.set_ylim(0, max(amounts) * 1.25)
ax.spines["top"].set_visible(False)
ax.spines["right"].set_visible(False)
fig.tight_layout()
fig.savefig(CHART_PNG, dpi=150)
plt.close(fig)
print(f"Wrote {CHART_PNG}")

